// NegocioMetricas.cs — metrica de negocio publicada sem SDK de metrica nenhum
//
// A ARMADILHA deste arquivo, e o motivo de ele nao usar o mesmo logger
// estruturado (Serilog) que o resto da aplicacao: o CloudWatch exige que a
// linha de log SEJA o objeto JSON do EMF, sem nada antes nem depois. Se voce
// mandar este payload pelo Serilog, ele embrulha a string dentro do PROPRIO
// envelope JSON dele (timestamp, level, message...) — e o "_aws" deixa de
// estar na RAIZ do evento. A extracao falha em silencio: nenhum erro, nenhum
// log de aviso, so a metrica que nunca aparece no CloudWatch. A correcao e
// escrever direto em Console.Out, fora do pipeline de log da aplicacao.

using System.Text.Json;

namespace Cadencia.Observabilidade;

public static class NegocioMetricas
{
    // Um metodo por evento de negocio — nao um metodo generico "PublicarMetrica" —
    // porque o NOME da metrica e o nome do efeito, nao um parametro livre.
    // Livre demais e como "log.Info(algumaCoisa)": tecnicamente funciona,
    // pedagogicamente nao ensina nada sobre o que aconteceu.
    public static void PedidoConfirmado(string servico = "Pedidos") =>
        Emitir(nome: "PedidoConfirmado", servico);

    public static void CobrancaProcessada(string servico = "Faturamento") =>
        Emitir(nome: "CobrancaProcessada", servico);

    private static void Emitir(string nome, string servico)
    {
        // "Dimensions" e uma lista de LISTAS: cada lista interna e um
        // conjunto de dimensao que gera uma metrica propria. Uma dimensao so
        // (Servico) e suficiente aqui — NUNCA adicione PedidoId ou CobrancaId
        // como dimensao: cada valor unico vira uma metrica de CloudWatch
        // nova, e customer-id-como-dimensao e a causa mais comum de fatura
        // de metrica customizada que ninguem sabe explicar.
        var payload = new Dictionary<string, object>
        {
            ["_aws"] = new Dictionary<string, object>
            {
                ["Timestamp"] = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                ["CloudWatchMetrics"] = new object[]
                {
                    new Dictionary<string, object>
                    {
                        ["Namespace"] = "Cadencia/Negocio",
                        ["Dimensions"] = new object[] { new[] { "Servico" } },
                        ["Metrics"] = new object[]
                        {
                            new Dictionary<string, object> { ["Name"] = nome, ["Unit"] = "Count" },
                        },
                    },
                },
            },
            ["Servico"] = servico,
            [nome] = 1,
        };

        // Console.Out, nao ILogger: esta linha PRECISA chegar ao driver
        // awslogs do conteiner exatamente como este JSON, sem prefixo de
        // nivel nem timestamp de outro formato na frente.
        Console.Out.WriteLine(JsonSerializer.Serialize(payload));
    }
}

// Ponto de chamada, dentro do endpoint que ja existe desde o L01/L51 — uma
// linha, no lugar exato onde o efeito de negocio se torna verdade:
//
//   await db.Pedidos.AddAsync(pedido);
//   await db.SaveChangesAsync();
//   NegocioMetricas.PedidoConfirmado();   // <- aqui, depois do commit, nao antes
//
// Antes do SaveChangesAsync a metrica mentiria sobre um pedido que pode nao
// ter sido persistido. E o mesmo raciocinio do health check de prontidao do
// L03: o sinal so vale alguma coisa se disser a verdade sobre o que JA aconteceu.
